// Static map + location content. Tile codes: see docs/ARCHITECTURE.md.
// Rows are generated by a tiny grid builder so layouts stay readable; the exported
// objects are plain data (MapDefinition / LocationDefinition).
import type { LocationDefinition, MapDefinition, MapProp } from "../game/types";
import { COND, LOC, MAP } from "./ids";

class Grid {
  readonly cells: string[][];
  constructor(
    readonly w: number,
    readonly h: number,
    fill = ".",
  ) {
    this.cells = Array.from({ length: h }, () => Array<string>(w).fill(fill));
  }
  set(x: number, y: number, c: string): void {
    if (x >= 0 && y >= 0 && x < this.w && y < this.h) this.cells[y][x] = c;
  }
  rect(x0: number, y0: number, x1: number, y1: number, c: string): void {
    for (let y = y0; y <= y1; y++) for (let x = x0; x <= x1; x++) this.set(x, y, c);
  }
  /** Sprinkle ',' (grassb) over plain grass with a deterministic hash. */
  variegate(seed: number): void {
    for (let y = 0; y < this.h; y++)
      for (let x = 0; x < this.w; x++) {
        if (this.cells[y][x] !== ".") continue;
        const n = Math.imul(x * 73856093 + y * 19349663 + seed * 83492791, 2654435761) >>> 0;
        if (n % 100 < 18) this.cells[y][x] = ",";
      }
  }
  rows(): string[] {
    return this.cells.map((r) => r.join(""));
  }
}

const P = (key: string, x: number, y: number): MapProp => ({ key, x, y });

// ---------------------------------------------------------------- map_starter (30 x 22)
function buildStarter(): MapDefinition {
  const W = 30;
  const H = 22;
  const g = new Grid(W, H);

  // Roads: vertical x=14 (y1..13), horizontal y=14 (x1..28); sidewalks either side.
  g.rect(13, 1, 13, 13, "s");
  g.rect(15, 1, 15, 13, "s");
  g.rect(14, 1, 14, 13, "R");
  g.rect(1, 13, 28, 13, "s");
  g.rect(1, 15, 28, 15, "s");
  g.rect(1, 14, 29, 14, "r");
  g.set(14, 14, "+");
  g.set(14, 11, "|");
  g.set(5, 14, "=");
  g.set(19, 14, "=");

  // Dirt paths: home + gazebo front yards, and the gap through the south hedge.
  g.rect(5, 11, 5, 12, "d");
  g.rect(9, 11, 11, 11, "d");
  g.set(10, 12, "d");
  g.rect(14, 16, 14, 20, "d");

  // Front-yard fence (y=12) with gaps at the two dirt paths.
  for (let x = 1; x <= 12; x++) if (x !== 5 && x !== 10) g.set(x, 12, "f");

  // Pond (top-left).
  g.rect(2, 2, 5, 4, "~");

  // South hedge row with the dirt gap, brick wall at the bottom.
  for (let x = 1; x <= 28; x++) if (x !== 14) g.set(x, 16, "h");
  g.rect(0, 21, W - 1, 21, "w");

  // Outer hedges: north, west, east (east keeps the gate on the road at y=14).
  g.rect(0, 0, W - 1, 0, "h");
  g.rect(0, 1, 0, 20, "h");
  g.rect(29, 1, 29, 20, "h");
  g.set(29, 14, "r");

  g.variegate(1);

  const props: MapProp[] = [
    P("house", 4, 8),
    P("gazebo", 9, 8),
    P("shop", 17, 10),
    P("cafe", 21, 10),
    // street furniture
    P("mailbox", 3, 13),
    P("bench", 7, 13),
    P("lamp", 13, 4),
    P("lamp", 15, 8),
    P("trafficsign", 15, 14),
    P("signboard", 25, 12),
    P("trash", 26, 12),
    P("signboard", 28, 13),
    // north-west: pond surroundings
    P("rock", 1, 1),
    P("rock", 6, 3),
    P("bush", 7, 5),
    P("tree", 8, 1),
    P("tree", 10, 4),
    P("bush", 12, 6),
    P("flower", 2, 6),
    P("flower", 3, 10),
    P("flower", 7, 10),
    P("flower", 12, 10),
    // north-east
    P("tree", 19, 2),
    P("tree", 25, 3),
    P("tree", 22, 6),
    P("tree", 17, 6),
    P("rock", 24, 1),
    P("bush", 20, 4),
    P("bush", 27, 7),
    P("flower", 18, 9),
    P("flower", 26, 9),
    P("flower", 23, 8),
    // south yard
    P("tree", 3, 18),
    P("tree", 9, 18),
    P("tree", 19, 18),
    P("tree", 25, 17),
    P("bush", 6, 19),
    P("bush", 22, 19),
    P("rock", 12, 19),
    P("rock", 16, 18),
    P("flower", 8, 17),
    P("flower", 17, 20),
    P("flower", 27, 19),
    P("bench", 11, 17),
  ];

  return {
    id: MAP.starter,
    name: "市區街區",
    width: W,
    height: H,
    rows: g.rows(),
    locationIds: [LOC.home, LOC.shop, LOC.cafe, LOC.park, LOC.gateEast],
    spawn: { x: 5, y: 11 },
    props,
  };
}

// ---------------------------------------------------------------- map_rural (24 x 18)
function buildRural(): MapDefinition {
  const W = 24;
  const H = 18;
  const g = new Grid(W, H);

  // Main dirt road from the west gate (0,9) east, a branch north to the farmhouse.
  g.rect(0, 9, 16, 9, "d");
  g.rect(15, 7, 15, 9, "d");
  g.rect(16, 9, 16, 13, "d");

  // Fenced crop field (south-east): 't' tilled soil (walkable paths), 'c' cabbage row, 'y' wheat row (impassable).
  // Soil paths: y=12 from the gate, x=18 down the west side, y=14 to the scarecrow at the east end.
  g.rect(18, 11, 21, 15, "t");
  g.rect(18, 11, 21, 11, "c");
  g.rect(18, 15, 21, 15, "c");
  g.rect(19, 13, 20, 13, "y");
  for (let x = 17; x <= 22; x++) {
    g.set(x, 10, "f");
    g.set(x, 16, "f");
  }
  for (let y = 10; y <= 16; y++) {
    g.set(17, y, "f");
    g.set(22, y, "f");
  }
  g.set(17, 12, "d"); // field gate (the work tile is in front of the scarecrow at (21,14))

  // Pond (south-west).
  g.rect(3, 12, 6, 15, "~");

  // Borders: fences north/east/west (west gate at y=9), hedge south.
  g.rect(0, 0, W - 1, 0, "f");
  g.rect(W - 1, 0, W - 1, H - 2, "f");
  g.rect(0, 0, 0, H - 2, "f");
  g.set(0, 9, "d");
  g.rect(0, H - 1, W - 1, H - 1, "h");

  g.variegate(7);

  const props: MapProp[] = [
    P("house", 14, 4),
    P("mailbox", 12, 5),
    P("signboard", 2, 8),
    P("bench", 11, 10),
    P("tree", 2, 2),
    P("tree", 6, 4),
    P("tree", 9, 1),
    P("tree", 20, 2),
    P("tree", 10, 13),
    P("tree", 1, 15),
    P("tree", 13, 15),
    P("tree", 8, 6),
    P("bush", 4, 6),
    P("bush", 12, 3),
    P("bush", 19, 6),
    P("bush", 8, 15),
    P("rock", 21, 7),
    P("rock", 7, 11),
    P("rock", 2, 11),
    P("rock", 12, 16),
    P("flower", 5, 8),
    P("flower", 10, 7),
    P("flower", 18, 4),
    P("flower", 12, 12),
    P("flower", 9, 16),
    P("flower", 4, 10),
    // crop garden beside the farmhouse + the scarecrow that marks the work spot in the field
    P("cabbage", 18, 8),
    P("cabbage", 19, 8),
    P("pumpkin", 20, 8),
    P("pumpkin", 21, 8),
    P("wheat", 17, 6),
    P("wheat", 18, 6),
    P("scarecrow", 21, 12),
  ];

  return {
    id: MAP.rural,
    name: "鄉村",
    width: W,
    height: H,
    rows: g.rows(),
    locationIds: [LOC.farm, LOC.field, LOC.gateWest],
    unlockConditionId: COND.unlockRural,
    spawn: { x: 1, y: 9 },
    props,
  };
}

// ---------------------------------------------------------------- interiors
/**
 * Small room: wall row on top (`wall` = 'i' cream / 'j' wood), trim ('v') on the sides and bottom,
 * `floor` inside, and a door mat ('m') in the bottom wall at doorX. Spawn = tile above the door.
 */
function buildInterior(
  id: string,
  name: string,
  w: number,
  h: number,
  wall: string,
  floor: string,
  doorX: number,
  locationIds: string[],
  props: MapProp[],
): MapDefinition {
  const g = new Grid(w, h, floor);
  g.rect(0, 0, w - 1, 0, wall);
  g.rect(0, 1, 0, h - 1, "v");
  g.rect(w - 1, 1, w - 1, h - 1, "v");
  g.rect(1, h - 1, w - 2, h - 1, "v");
  g.set(doorX, h - 1, "m");
  return { id, name, width: w, height: h, rows: g.rows(), locationIds, spawn: { x: doorX, y: h - 2 }, props };
}

