const homeIn = buildInterior(MAP.homeIn, "我的家（室內）", 10, 8, "i", "W", 4, [LOC.homeBed, LOC.homeExit], [
  P("window", 4, 0),
  P("shelf", 6, 0),
  P("shelf", 7, 0),
  P("rug", 2, 3),
  P("bed", 1, 1),
  P("table", 2, 1),
  P("tablelamp", 2, 1),
  P("table", 6, 4),
  P("chair", 5, 4),
  P("chair", 7, 4),
]);

